-- Enforce branch-aware authorization on core operational records.
insert into public.role_permissions(role,permission,allowed) values ('branch_manager','payments.manage',true),('technician','inventory.view',true) on conflict(role,permission) do update set allowed=excluded.allowed;
create or replace function public.assign_repair_engineer(p_repair_id uuid,p_engineer_id uuid,p_notes text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare c uuid; eid uuid; aid uuid; begin if not public.has_permission('repairs.manage') then raise exception 'Permission denied'; end if; c:=public.get_my_company_id(); if c is null then raise exception 'Company not found'; end if; select company_id into eid from public.engineers where id=p_engineer_id; if eid is null or eid<>c then raise exception 'Engineer not found'; end if; if not exists(select 1 from public.repairs where id=p_repair_id and company_id=c and public.user_has_branch_access(branch_id)) then raise exception 'Repair not found'; end if; update public.repair_assignments set unassigned_at=now() where repair_id=p_repair_id and company_id=c and unassigned_at is null; update public.repairs set engineer_id=p_engineer_id,assigned_at=now(),technician=(select name from public.engineers where id=p_engineer_id) where id=p_repair_id and company_id=c; insert into public.repair_assignments(company_id,repair_id,engineer_id,assigned_by,notes) values(c,p_repair_id,p_engineer_id,auth.uid(),p_notes) returning id into aid; return aid; end; $$;
revoke all on function public.assign_repair_engineer(uuid,uuid,text) from public,anon; grant execute on function public.assign_repair_engineer(uuid,uuid,text) to authenticated;
create or replace function public.set_default_branch_on_insert() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.branch_id is null then select branch_id into new.branch_id from public.user_branches where profile_id=auth.uid() order by created_at asc limit 1; if new.branch_id is null then select id into new.branch_id from public.branches where company_id=new.company_id and is_main=true limit 1; end if; end if; return new; end; $$;
revoke all on function public.set_default_branch_on_insert() from public,anon,authenticated;
drop trigger if exists inventory_default_branch on public.inventory; create trigger inventory_default_branch before insert on public.inventory for each row execute function public.set_default_branch_on_insert();
drop trigger if exists repairs_default_branch on public.repairs; create trigger repairs_default_branch before insert on public.repairs for each row execute function public.set_default_branch_on_insert();
drop trigger if exists sales_default_branch on public.sales; create trigger sales_default_branch before insert on public.sales for each row execute function public.set_default_branch_on_insert();
drop trigger if exists financial_default_branch on public.financial_transactions; create trigger financial_default_branch before insert on public.financial_transactions for each row execute function public.set_default_branch_on_insert();
drop trigger if exists invoices_default_branch on public.invoices; create trigger invoices_default_branch before insert on public.invoices for each row execute function public.set_default_branch_on_insert();
drop trigger if exists debt_default_branch on public.customer_debt_ledger; create trigger debt_default_branch before insert on public.customer_debt_ledger for each row execute function public.set_default_branch_on_insert();
drop trigger if exists engineer_ledger_default_branch on public.engineer_part_ledger; create trigger engineer_ledger_default_branch before insert on public.engineer_part_ledger for each row execute function public.set_default_branch_on_insert();
drop trigger if exists audit_default_branch on public.audit_logs; create trigger audit_default_branch before insert on public.audit_logs for each row execute function public.set_default_branch_on_insert();
drop policy if exists "Company isolation - inventory" on public.inventory; drop policy if exists "Users can create inventory in their company" on public.inventory; drop policy if exists "Users can delete inventory in their company" on public.inventory; drop policy if exists "Users can update inventory in their company" on public.inventory; drop policy if exists "Users can view inventory in their company" on public.inventory; create policy inventory_branch_select on public.inventory for select to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id)); create policy inventory_branch_write on public.inventory for all to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('inventory.manage')) with check(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('inventory.manage'));
drop policy if exists "Company isolation - repairs" on public.repairs; drop policy if exists "Users can create repairs in their company" on public.repairs; drop policy if exists "Users can delete repairs in their company" on public.repairs; drop policy if exists "Users can update repairs in their company" on public.repairs; drop policy if exists "Users can view repairs in their company" on public.repairs; create policy repairs_branch_select on public.repairs for select to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id)); create policy repairs_branch_write on public.repairs for all to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('repairs.manage')) with check(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('repairs.manage'));
drop policy if exists "Company isolation - sales" on public.sales; drop policy if exists "Users can create sales in their company" on public.sales; drop policy if exists "Users can delete sales in their company" on public.sales; drop policy if exists "Users can update sales in their company" on public.sales; drop policy if exists "Users can view sales in their company" on public.sales; create policy sales_branch_select on public.sales for select to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id)); create policy sales_branch_write on public.sales for all to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('sales.manage')) with check(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('sales.manage'));
drop policy if exists "Company managers can insert financial transactions" on public.financial_transactions; drop policy if exists "Company managers can update financial transactions" on public.financial_transactions; drop policy if exists "Company users can view financial transactions" on public.financial_transactions; create policy financial_branch_select on public.financial_transactions for select to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id)); create policy financial_branch_write on public.financial_transactions for insert to authenticated with check(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('payments.manage')); create policy financial_branch_update on public.financial_transactions for update to authenticated using(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('payments.manage')) with check(company_id=public.get_my_company_id() and public.user_has_branch_access(branch_id) and public.has_permission('payments.manage'));